import{advance,applyInput,snapshot,RULES_VERSION,eliminate}from'../sim.js';
import{resolveDuel,forfeitDuel}from'../duel.js';
import{liveSnapshot}from'../presence.js';
import{rememberLive}from'./live-cache.js';
const runners=new Map(),sessions=new Map();
const sameDB=(a,b)=>a===b||!a.sqlite&&!b.sqlite;
let owner;const sleep=ms=>new Promise(r=>setTimeout(r,ms));
const hash=async token=>Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(token))),x=>x.toString(16).padStart(2,'0')).join('');
function response(body,status=200){return new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});}
async function batch(env,statements){if(env.DB.batch)return env.DB.batch(statements);const out=[];for(const s of statements)out.push(await s.all());return out;}
export async function pumpRoom(env,code){owner??=crypto.randomUUID();const now=Date.now(),read=await batch(env,[env.DB.prepare('INSERT INTO room_coordinator(code,owner,lease_until) VALUES(?,?,?) ON CONFLICT(code) DO UPDATE SET owner=excluded.owner,lease_until=excluded.lease_until WHERE room_coordinator.lease_until<? OR room_coordinator.owner=?').bind(code,owner,now+4000,now,owner),env.DB.prepare('SELECT state,version FROM rooms WHERE code=?').bind(code),env.DB.prepare('SELECT player_id,seq,payload,updated_at FROM room_inputs WHERE code=?').bind(code)]);if(read[0].meta.changes!==1)return{owned:false};
 const row=read[1].results[0],inputs=read[2].results;if(!row)return{owned:true,stop:true};const s=JSON.parse(row.state);if(s.closed||s.rulesVersion!==RULES_VERSION||s.phase==='finished')return{owned:true,stop:true};const newest=Math.max(0,...inputs.map(i=>i.updated_at));if(now-newest>3500)return{owned:true,stop:true};
 advance(s,now);for(const i of inputs){const p=s.players.find(p=>p.id===i.player_id);if(!p||p.connected===false)continue;p.lastSeen=Math.max(p.lastSeen||0,i.updated_at);if(i.seq>p.lastSeq)applyInput(s,p,JSON.parse(i.payload));}
 for(const p of s.players)if(!p.bot&&p.connected!==false&&now-p.lastSeen>(s.mode==='duel'?20000:60000)){if(s.mode==='duel')forfeitDuel(s,p);else if(s.phase!=='lobby'){eliminate(s,p);p.connected=false;}}
 resolveDuel(s);s.revision=row.version+1;s.coordinatorMark=owner+':'+now+':'+Math.random();const live=liveSnapshot(s),write=await batch(env,[env.DB.prepare('UPDATE rooms SET state=?,version=version+1,updated_at=? WHERE code=? AND version=? AND EXISTS(SELECT 1 FROM room_coordinator WHERE code=? AND owner=?)').bind(JSON.stringify(s),now,code,row.version,code,owner),env.DB.prepare("INSERT INTO room_live(code,state,version,updated_at) SELECT ?,?,?,? WHERE EXISTS(SELECT 1 FROM rooms WHERE code=? AND version=? AND json_extract(state,'$.coordinatorMark')=?) ON CONFLICT(code) DO UPDATE SET state=excluded.state,version=excluded.version,updated_at=excluded.updated_at WHERE excluded.version>room_live.version").bind(code,JSON.stringify(live),s.revision,now,code,s.revision,s.coordinatorMark)]);if(write[0].meta.changes!==1)return{owned:true,retry:true};rememberLive(env,live);return{owned:true,version:s.revision,stop:s.phase==='finished'||s.closed};
}
// A leased room runs at game cadence in memory. D1 checkpoints and remote mailboxes
// run in the background; their round trips never gate the next movement frame.
function mergeInputs(entry,rows){for(const row of rows){const old=entry.pending.get(row.player_id);if(!old||row.seq>old.seq)entry.pending.set(row.player_id,row);}}
function applyQueued(s,rows,now){advance(s,now);for(const i of rows){const p=s.players.find(p=>p.id===i.player_id);if(!p||p.connected===false)continue;p.lastSeen=Math.max(p.lastSeen||0,i.updated_at);if(i.seq>p.lastSeq)applyInput(s,p,typeof i.payload==='string'?JSON.parse(i.payload):i.payload);}for(const p of s.players)if(!p.bot&&p.connected!==false&&now-p.lastSeen>(s.mode==='duel'?20000:60000)){if(s.mode==='duel')forfeitDuel(s,p);else if(s.phase!=='lobby'){eliminate(s,p);p.connected=false;}}resolveDuel(s);}
export function reconcileMutation(previous,next){const m=next.controlMutation;if(!previous||m?.operation!=='leave'||m.key===previous.controlMutation?.key||previous.round!==next.round||previous.mode!==next.mode||previous.duel?.round!==next.duel?.round||!['flight','battle'].includes(previous.phase))return next;previous.controlMutation={...m};const p=previous.players.find(p=>p.id===m.player);if(!p)return next;if(previous.mode==='duel')forfeitDuel(previous,p);else if(p.id===previous.host)previous.closed=true;else{eliminate(previous,p);p.connected=false;}return previous;}
async function loadStage(entry){const now=Date.now(),code=entry.code,env=entry.env;owner??=crypto.randomUUID();const r=await batch(env,[env.DB.prepare('INSERT INTO room_coordinator(code,owner,lease_until) VALUES(?,?,?) ON CONFLICT(code) DO UPDATE SET owner=excluded.owner,lease_until=excluded.lease_until WHERE room_coordinator.lease_until<? OR room_coordinator.owner=?').bind(code,owner,now+5000,now,owner),env.DB.prepare('SELECT state,version FROM rooms WHERE code=?').bind(code),env.DB.prepare('SELECT player_id,seq,payload,updated_at FROM room_inputs WHERE code=?').bind(code)]);if(r[0].meta.changes!==1||!r[1].results[0])return false;const row=r[1].results[0],next=JSON.parse(row.state);const old=entry.stage,unchanged=old&&row.version===old.version&&next.coordinatorMark===old.s.coordinatorMark;entry.stage={s:unchanged?old.s:reconcileMutation(old?.s,next),version:row.version,serial:0,leaseUntil:now+5000};mergeInputs(entry,r[2].results);entry.reload=false;return true;}
function broadcast(entry){const stage=entry.stage;if(!stage)return;stage.s.revision=stage.version+(++stage.serial)/10000;rememberLive(entry.env,liveSnapshot(stage.s));}
async function saveStage(entry){const stage=entry.stage;if(!stage)return false;const env=entry.env,code=entry.code,now=Date.now(),nextVersion=stage.version+1,mark=owner+':'+now+':'+Math.random(),saved={...stage.s,revision:nextVersion,coordinatorMark:mark},stateJson=JSON.stringify(saved),liveJson=JSON.stringify(liveSnapshot(saved));const r=await batch(env,[env.DB.prepare('UPDATE rooms SET state=?,version=version+1,updated_at=? WHERE code=? AND version=? AND EXISTS(SELECT 1 FROM room_coordinator WHERE code=? AND owner=?)').bind(stateJson,now,code,stage.version,code,owner),env.DB.prepare("INSERT INTO room_live(code,state,version,updated_at) SELECT ?,?,?,? WHERE EXISTS(SELECT 1 FROM rooms WHERE code=? AND version=? AND json_extract(state,'$.coordinatorMark')=?) ON CONFLICT(code) DO UPDATE SET state=excluded.state,version=excluded.version,updated_at=excluded.updated_at WHERE excluded.version>room_live.version").bind(code,liveJson,nextVersion,now,code,nextVersion,mark),env.DB.prepare('UPDATE room_coordinator SET lease_until=? WHERE code=? AND owner=?').bind(now+5000,code,owner)]);if(r[0].meta.changes!==1){entry.reload=true;return false;}stage.version=nextVersion;stage.serial=0;stage.leaseUntil=now+5000;stage.s.coordinatorMark=mark;broadcast(entry);return true;}
export async function pauseControls(env,code){const e=runners.get(code);if(!e||!sameDB(e.env.DB,env.DB))return()=>{};e.paused=true;if(e.saving)await e.saving;if(e.stage&&!e.reload)await saveStage(e);return()=>{e.reload=true;e.paused=false;};}
function residentState(env,code){const e=runners.get(code);return e&&sameDB(e.env.DB,env.DB)&&e.stage&&!e.reload&&e.stage.leaseUntil>Date.now()?e.stage.s:null;}
export function kickRoom(env,code){if(runners.has(code))return runners.get(code).promise;const e={env,code,pending:new Map(),stage:null,paused:false,reload:false,saving:null,reading:null,lastRead:0,lastSave:0};runners.set(code,e);e.promise=(async()=>{const end=Date.now()+20000;try{if(!await loadStage(e))return;while(Date.now()<end){if(e.paused){await sleep(20);continue;}if(e.reload){if(e.saving)await e.saving;if(!await loadStage(e))return;}const now=Date.now(),s=e.stage.s,newest=Math.max(0,...[...e.pending.values()].map(i=>i.updated_at));if(s.closed||s.rulesVersion!==RULES_VERSION||s.phase==='finished'||now-newest>3500)break;if(e.stage.leaseUntil>now){applyQueued(s,e.pending.values(),now);broadcast(e);}else e.reload=true;
 if(!e.reading&&now-e.lastRead>220){e.lastRead=now;e.reading=env.DB.prepare('SELECT player_id,seq,payload,updated_at FROM room_inputs WHERE code=?').bind(code).all().then(r=>mergeInputs(e,r.results)).catch(()=>{}).finally(()=>{e.reading=null;});}
 if(!e.saving&&now-e.lastSave>350){e.lastSave=now;e.saving=saveStage(e).catch(()=>{e.reload=true;}).finally(()=>{e.saving=null;});}await sleep(40);}
 }finally{if(e.saving)await e.saving;if(e.stage&&!e.reload){try{await saveStage(e);}catch{}}if(e.reading)await e.reading;runners.delete(code);await env.DB.prepare('UPDATE room_coordinator SET lease_until=0 WHERE code=? AND owner=?').bind(code,owner).run();}})();return e.promise;}

export async function queueControls(req,env,code,b,ctx){if(!Number.isSafeInteger(b.seq)||b.seq<0)return response({error:'입력 번호를 확인하세요.'},400);const token=(req.headers.get('authorization')||'').replace(/^Bearer /,'');if(!token)return response({error:'입장 정보가 필요해요.'},401);const tokenHash=await hash(token),key=code+':'+tokenHash,now=Date.now();let session=sessions.get(key),s=residentState(env,code);
 if(!session||session.until<now||b.wantState){if(!s){const row=await env.DB.prepare('SELECT state FROM rooms WHERE code=?').bind(code).first();if(!row)return response({error:'방을 찾을 수 없어요.'},404);s=JSON.parse(row.state);}const p=s.players.find(p=>p.tokenHash===tokenHash&&p.connected!==false);if(!p||s.closed)return response({error:'입장 정보가 만료됐어요.'},401);if(s.rulesVersion!==RULES_VERSION)return response({error:'새로고침 후 새 방을 만들어 주세요.',upgrade:true},409);session={id:p.id,until:now+10000};sessions.set(key,session);if(sessions.size>512)for(const[k,v]of sessions)if(v.until<now)sessions.delete(k);}
 const task=kickRoom(env,code),entry=runners.get(code);if(entry)mergeInputs(entry,[{player_id:session.id,seq:b.seq,payload:b,updated_at:now}]);if(ctx?.waitUntil)ctx.waitUntil(task.catch(()=>{}));
 await env.DB.prepare('INSERT INTO room_inputs(code,player_id,seq,payload,updated_at) VALUES(?,?,?,?,?) ON CONFLICT(code,player_id) DO UPDATE SET seq=excluded.seq,payload=excluded.payload,updated_at=excluded.updated_at WHERE excluded.seq>room_inputs.seq').bind(code,session.id,b.seq,JSON.stringify(b),now).run();
 if(!ctx?.waitUntil)await task;
 if(b.wantState&&!s){const row=await env.DB.prepare('SELECT state FROM rooms WHERE code=?').bind(code).first();if(row)s=JSON.parse(row.state);}
 s=residentState(env,code)||s;return response({queued:true,seq:b.seq,...(b.wantState&&s?{state:snapshot(s,session.id)}:{})},202);
}
